import 'unit_model.dart';
import 'units_data.dart';

void applyFinalCurriculumStageSplit() {
  UnitsData.units[44] = _unit(45, 'مفهوم الكسر والجزء من الكل', '10–13 سنة', 'فهم الكسر بوصفه جزءاً من كل متساوي الأجزاء.', 'ما هو الكسر؟', 'الكسر يصف جزءاً من كل مقسم إلى أجزاء متساوية.', ['1/2 نصف', '3/4 ثلاثة أرباع'], [_q('في 3/4 ما البسط؟', ['3', '4', '7'], 0), _q('في 3/4 ما المقام؟', ['3', '4', '1'], 1)]);
  UnitsData.units[45] = _unit(46, 'الكسور المتكافئة والمقارنة والعمليات', '10–13 سنة', 'مقارنة الكسور والتعرف على الكسور المتكافئة وإجراء عمليات بسيطة.', 'نقارن ونحسب بالكسور', 'الكسور المتكافئة تمثل الكمية نفسها.', ['1/2 = 2/4', '1/4 < 3/4'], [_q('أي كسر يكافئ 1/2؟', ['1/3', '2/4', '3/4'], 1), _q('1/4 + 1/4 = ؟', ['1/2', '1/4', '3/4'], 0)]);
  UnitsData.units[46] = _unit(47, 'الأعداد العشرية والقيمة المكانية', '10–13 سنة', 'فهم الأعشار والأجزاء من مئة وقراءة الأعداد العشرية.', 'ما بعد الفاصلة', 'الأرقام بعد الفاصلة تمثل أجزاء من الواحد.', ['0.5 = 5/10', '1.25 = 1 + 25/100'], [_q('0.5 يساوي أي كسر؟', ['1/2', '1/5', '5/100'], 0), _q('ما قيمة 5 في 1.25؟', ['5 أعشار', '5 أجزاء من مئة', '5 آحاد'], 1)]);
  UnitsData.units[47] = _unit(48, 'العمليات على الأعداد العشرية', '10–13 سنة', 'الجمع والطرح والضرب والقسمة على الأعداد العشرية.', 'نحسب بالعشريات', 'نرتب الفاصلة عند الجمع والطرح.', ['1.2 + 0.3 = 1.5', '1.9 + 1.9 = 3.8'], [_q('1.2 + 0.3 = ؟', ['1.3', '1.5', '1.7'], 1), _q('1.9 + 1.9 = ؟', ['3.6', '3.8', '4.0'], 1)]);
  UnitsData.units[48] = _unit(49, 'النسبة ومعدل الوحدة', '12–15 سنة', 'فهم النسبة ومقارنة كميتين واستخدام معدل الوحدة.', 'نقارن كميتين بالنسبة', 'النسبة تقارن بين كميتين، ومعدل الوحدة يبين كمية واحدة مقابل وحدة واحدة.', ['2:3 نسبة', '12 تفاحة إلى 4 أطفال = 3 تفاحات لكل طفل'], [_q('2:3 تمثل؟', ['نسبة', 'معادلة', 'كسر عشري فقط'], 0), _q('12 تفاحة لـ4 أطفال، كم لكل طفل؟', ['2', '3', '4'], 1)]);
  UnitsData.units[49] = _unit(50, 'التناسب والنسبة المئوية', '12–15 سنة', 'حل التناسبات البسيطة وفهم النسبة المئوية.', 'نحل التناسب ونفهم النسبة المئوية', 'التناسب يعني تساوي نسبتين، والنسبة المئوية جزء من 100.', ['2/3 = 4/6', '50% = 1/2 = 0.5'], [_q('50% يساوي؟', ['1/2', '1/4', '2/5'], 0), _q('إذا كان 2/3 = x/6 فما x؟', ['2', '4', '6'], 1)]);
  UnitsData.units[50] = _unit(51, 'المتغيرات والتعبيرات الجبرية', '13–16 سنة', 'التعرف على المتغيرات والثوابت والمعاملات وتبسيط التعبيرات.', 'ننتقل إلى الرموز', 'المتغير يمثل قيمة يمكن أن تتغير.', ['x + 3', '2x + 5', '3x + 2x = 5x'], [_q('في 2x + 5 ما المتغير؟', ['2', 'x', '5'], 1), _q('3x + 2x = ؟', ['5x', '6x', 'x'], 0)]);
  UnitsData.units[51] = _unit(52, 'المعادلات والمتباينات والمسائل الجبرية', '13–16 سنة', 'حل المعادلات والمتباينات والتحقق من الحل.', 'نحل ونحقق', 'نستخدم العمليات العكسية لعزل المتغير ثم نتحقق من الحل.', ['x + 3 = 7', '2x = 10', 'x > 4'], [_q('إذا كان x + 3 = 7 فما قيمة x؟', ['3', '4', '5'], 1), _q('x > 4، أي قيمة تحقق المتباينة؟', ['3', '4', '6'], 2)], [_q('2x = 10، x = ؟', ['4', '5', '6'], 1), _q('x + 5 = 12، x = ؟', ['5', '7', '8'], 1), _q('x > 4، أي قيمة صحيحة؟', ['2', '4', '6'], 2)]);
}

UnitModel _unit(int n, String title, String age, String description, String learnTitle, String explanation, List<String> examples, List<ChoiceQuestion> quiz, [List<ChoiceQuestion>? assessment]) {
  return UnitModel(id: 'unit_${n.toString().padLeft(2, '0')}', order: n, titleAr: title, ageRangeAr: age, descriptionAr: description, activities: [LessonActivityConfig(titleAr: learnTitle, explanationAr: explanation, examplesAr: examples), MultipleChoiceActivityConfig(quiz), AssessmentActivityConfig(titleAr: 'اختبار الوحدة $n', questions: assessment ?? quiz)]);
}

ChoiceQuestion _q(String question, List<String> options, int correct) => ChoiceQuestion(questionAr: question, options: options, correctIndex: correct);
